        queue = deque([(start, 'root')])
        while queue:
            current, direction = queue.popleft()
            if current.value == target:
                return True
            if direction == 'left':
                if current.right != -1:
                    queue.append((tree[current.right], 'right'))
            elif direction == 'right':
                if current.left != -1:
                    queue.append((tree[current.left], 'left'))
            else:
                if current.left != -1:
                    queue.append((tree[current.left], 'left'))
                if current.right != -1:
                    queue.append((tree[current.right], 'right'))
        return False

    for i in range(n):
        if not bfs_search(tree[i], i + 1):
            failures += 1

    return failures

