from collections import deque, defaultdict

def find_failures(n, nodes):
    graph = defaultdict(list)
    parent = {}

    for i, (v, l, r) in enumerate(nodes):
        if l != -1:
            graph[i].append(l)
            parent[l] = i
        if r != -1:
            graph[i].append(r)
            parent[r] = i

    def bfs(start, target):
        queue = deque([(start, None)])
        visited = set()

        while queue:
            current, prev = queue.popleft()
            if current in visited:
                continue
            visited.add(current)

            if nodes[current][0] == target:
                return True

            for neighbor in graph[current]:
                if neighbor != prev:
                    queue.append((neighbor, current))

        return False

    failures = 0
    for i, (v, _, _) in enumerate(nodes):
        if not bfs(i, v):
            failures += 1

    return failures

